// 完整Time2作者闭包：只选择已编译真实provider，不能由文件声明完成、免除阶段或提交函数。
#include "exact_time_profile.hpp"
#include "resident/facility_claims/facility_claims_codec.hpp"
#include "resident/storage/common_codec.hpp"
#include <algorithm>
#include <set>
#include <stdexcept>
namespace hanmo::resident {
namespace {
Outcome<ExactProviderId> provider(const StableId& name){for(unsigned i=0;i<=static_cast<unsigned>(ExactProviderId::facility_claims);++i)if(name==exact_provider_key(static_cast<ExactProviderId>(i)))return {true,static_cast<ExactProviderId>(i),{}};return {false,{},common_failure("UnknownExactPhaseProvider",name,ErrorKind::unsupported_capability).error};}
// 原领域schema地址与调度provider键不同：travel仍归同一motion writer，不改SourceRef域名。
Outcome<ExactProviderId> action_owner_provider(const StableId& domain){if(domain=="travel")return {true,ExactProviderId::motion,{}};if(domain=="craft")return {true,ExactProviderId::crafting,{}};if(domain=="private_shops")return {true,ExactProviderId::commerce,{}};if(domain=="personal_appointments"||domain=="contact_inquiries"||domain=="visit_appointment_meetings")return {true,ExactProviderId::interaction,{}};return provider(domain);}
}
bool exact_complete_selected(const ExactTimeProfile& p){return p.profile_id==exact_complete_profile_id&&p.complete.has_value()&&p.macro_providers.empty()&&p.supply_report_subscriptions.empty();}
Outcome<CompleteExactTimeSelection> decode_complete_exact_time_selection(const BoundaryValue& value){try{using namespace boundary;fields(value,{"profile","scale_ref","phase_providers","action_time_profiles","facility_claims"},{},"world_time");if(object(value,"world_time").size()!=5||get_string(value,"profile","world_time")!=exact_complete_profile_id)fail("InvalidCompleteTimeProfile","world_time");CompleteExactTimeSelection out;std::set<ExactProviderId> providers;for(const auto& row:array(field(value,"phase_providers","world_time"),"phase_providers")){fields(row,{"provider","profile_id","version"},{},"phase_provider");if(object(row,"phase_provider").size()!=3)fail("DuplicateExactProviderField","phase_provider");auto kind=provider(get_string(row,"provider","phase_provider"));if(!kind.ok)return {false,{},std::move(kind.error)};ExactPhaseSelection selection{kind.value,get_string(row,"profile_id","phase_provider"),get_int(row,"version","phase_provider")};if(selection.profile_id.empty()||selection.version<=0||!providers.insert(selection.provider).second)fail("InvalidExactPhaseSelection","phase_provider");out.phase_providers.push_back(std::move(selection));}if(out.phase_providers.empty())fail("MissingCompleteExactProviders","phase_providers");std::set<StableId> actions;for(const auto& row:array(field(value,"action_time_profiles","world_time"),"action_time_profiles")){fields(row,{"action_kind","profile_id","version"},{},"action_time_profile");if(object(row,"action_time_profile").size()!=3)fail("DuplicateActionTimeProfileField","action_time_profile");ExactActionTimeSelection selected{get_string(row,"action_kind","action_time_profile"),get_string(row,"profile_id","action_time_profile"),get_int(row,"version","action_time_profile")};if(selected.action_kind.empty()||selected.profile_id.empty()||selected.version<=0||!actions.insert(selected.action_kind).second)fail("InvalidActionTimeSelection","action_time_profile");out.action_time_profiles.push_back(std::move(selected));}auto facilities=decode_facility_claims_catalog(field(value,"facility_claims","world_time"));if(!facilities.ok)return {false,{},std::move(facilities.error)};out.facility_claims=std::move(facilities.value);return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}catch(const std::bad_alloc&){return {false,{},common_failure("ExactTimeSelectionResourceExhausted","world_time",ErrorKind::internal).error};}catch(const std::length_error&){return {false,{},common_failure("ExactTimeSelectionResourceExhausted","world_time",ErrorKind::internal).error};}}
Outcome<CompleteExactTimeRuntime> compose_complete_exact_time_profile(const ExactTimeProfile& profile,const std::vector<ExactPhaseRegistration>& providers,const std::vector<ActionTimeRegistration>& actions,const std::vector<StableId>& legacy,const std::vector<FacilityHolderRegistration>& holders){try{if(!exact_complete_selected(profile))return {false,{},common_failure("CompleteExactTimeSelectionRequired","world_time").error};auto scale=validate_time_scale(profile.scale_ref);if(!scale.ok)return {false,{},std::move(scale.error)};auto graph=compose_exact_phase_graph(providers,profile.complete->phase_providers,legacy);if(!graph.ok)return {false,{},std::move(graph.error)};CompleteExactTimeRuntime out;out.phase_graph=std::move(graph.value);for(const auto& selected:profile.complete->action_time_profiles){const ActionTimeRegistration* found=nullptr;for(const auto& reg:actions)if(reg.action_kind==selected.action_kind&&reg.profile_id==selected.profile_id&&reg.profile_version==selected.version){if(found)return {false,{},common_failure("DuplicateCompiledActionTimeProvider",selected.action_kind).error};found=&reg;}if(!found)return {false,{},common_failure("MissingCompiledActionTimeProvider",selected.action_kind,ErrorKind::unsupported_capability).error};auto owner=action_owner_provider(found->owner_domain);if(!owner.ok)return {false,{},std::move(owner.error)};if(std::none_of(out.phase_graph.providers.begin(),out.phase_graph.providers.end(),[&](const auto& p){return p.provider==owner.value;}))return {false,{},common_failure("MissingActionTimePhaseOwner",selected.action_kind,ErrorKind::unsupported_capability).error};out.action_times.push_back(*found);}auto valid=validate_action_time_registry(out.action_times);if(!valid.ok)return {false,{},std::move(valid.error)};out.facility_claims=profile.complete->facility_claims;
    const ExactPhaseRegistration* facility_phase=nullptr;for(const auto& p:out.phase_graph.providers)if(p.provider==ExactProviderId::facility_claims)facility_phase=&p;
    if(facility_phase){auto compiled=compile_facility_holder_profiles(holders);if(!compiled.ok)return {false,{},std::move(compiled.error)};if(compiled.value.empty())return {false,{},common_failure("MissingFacilityHolderAdapter","facility_claims",ErrorKind::unsupported_capability).error};std::set<ExactStage> declared(facility_phase->stages.begin(),facility_phase->stages.end()),actual;for(const auto& h:compiled.value)actual.insert(h.until_stage);if(actual!=declared)return {false,{},common_failure("FacilityHolderPhaseSelectionMismatch","facility_claims").error};out.facility_holder_profiles=std::move(compiled.value);}
    else if(!out.facility_claims.selected_slots.empty())return {false,{},common_failure("MissingFacilityPhaseOwner","facility_claims",ErrorKind::unsupported_capability).error};
    return {true,std::move(out),{}};}catch(const std::bad_alloc&){return {false,{},common_failure("ExactTimeCompositionResourceExhausted","world_time",ErrorKind::internal).error};}catch(const std::length_error&){return {false,{},common_failure("ExactTimeCompositionResourceExhausted","world_time",ErrorKind::internal).error};}}
}
